// n8n bloquea require('crypto') Y el acceso a $env, asi que:
//  - el HMAC-SHA256 va en JS puro (verificado contra crypto.createHmac)
//  - el secreto va embebido (n8n esta protegido por autenticacion)

// HMAC-SHA256 en JS puro (n8n Code node no permite require('crypto'))
function hmacSha256Hex(keyStr, msgStr) {
  const K = [];
  let cnt = 0;
  for (let n2 = 2; cnt < 64; n2++) {
    let isP = true;
    for (let f = 2; f * f <= n2; f++) if (n2 % f === 0) { isP = false; break; }
    if (isP) { K.push(Math.floor((Math.cbrt(n2) % 1) * 4294967296) >>> 0); cnt++; }
  }
  const H0 = [];
  let c2 = 0;
  for (let n3 = 2; c2 < 8; n3++) {
    let isP = true;
    for (let f = 2; f * f <= n3; f++) if (n3 % f === 0) { isP = false; break; }
    if (isP) { H0.push(Math.floor((Math.sqrt(n3) % 1) * 4294967296) >>> 0); c2++; }
  }

  function utf8Bytes(s) {
    const out = [];
    for (let i = 0; i < s.length; i++) {
      let c = s.charCodeAt(i);
      if (c < 0x80) out.push(c);
      else if (c < 0x800) { out.push(0xc0 | (c >> 6), 0x80 | (c & 63)); }
      else if (c >= 0xd800 && c <= 0xdbff) {
        const c2b = s.charCodeAt(++i);
        const cp = 0x10000 + ((c - 0xd800) << 10) + (c2b - 0xdc00);
        out.push(0xf0 | (cp >> 18), 0x80 | ((cp >> 12) & 63), 0x80 | ((cp >> 6) & 63), 0x80 | (cp & 63));
      } else { out.push(0xe0 | (c >> 12), 0x80 | ((c >> 6) & 63), 0x80 | (c & 63)); }
    }
    return out;
  }

  function sha256Bytes(bytes) {
    const H = H0.slice();
    const ml = bytes.length * 8;
    const msg = bytes.slice();
    msg.push(0x80);
    while (msg.length % 64 !== 56) msg.push(0);
    const hi = Math.floor(ml / 4294967296);
    const lo = ml >>> 0;
    msg.push((hi >>> 24) & 255, (hi >>> 16) & 255, (hi >>> 8) & 255, hi & 255);
    msg.push((lo >>> 24) & 255, (lo >>> 16) & 255, (lo >>> 8) & 255, lo & 255);

    const w = new Array(64);
    for (let i = 0; i < msg.length; i += 64) {
      for (let t = 0; t < 16; t++) {
        w[t] = ((msg[i + t * 4] << 24) | (msg[i + t * 4 + 1] << 16) | (msg[i + t * 4 + 2] << 8) | msg[i + t * 4 + 3]) >>> 0;
      }
      for (let t = 16; t < 64; t++) {
        const s0 = (((w[t - 15] >>> 7) | (w[t - 15] << 25)) ^ ((w[t - 15] >>> 18) | (w[t - 15] << 14)) ^ (w[t - 15] >>> 3)) >>> 0;
        const s1 = (((w[t - 2] >>> 17) | (w[t - 2] << 15)) ^ ((w[t - 2] >>> 19) | (w[t - 2] << 13)) ^ (w[t - 2] >>> 10)) >>> 0;
        w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
      }
      let a = H[0], b = H[1], c = H[2], d = H[3], e = H[4], f = H[5], g = H[6], h = H[7];
      for (let t = 0; t < 64; t++) {
        const S1 = (((e >>> 6) | (e << 26)) ^ ((e >>> 11) | (e << 21)) ^ ((e >>> 25) | (e << 7))) >>> 0;
        const ch = ((e & f) ^ (~e & g)) >>> 0;
        const t1 = (h + S1 + ch + K[t] + w[t]) >>> 0;
        const S0 = (((a >>> 2) | (a << 30)) ^ ((a >>> 13) | (a << 19)) ^ ((a >>> 22) | (a << 10))) >>> 0;
        const mj = ((a & b) ^ (a & c) ^ (b & c)) >>> 0;
        const t2 = (S0 + mj) >>> 0;
        h = g; g = f; f = e; e = (d + t1) >>> 0;
        d = c; c = b; b = a; a = (t1 + t2) >>> 0;
      }
      H[0] = (H[0] + a) >>> 0; H[1] = (H[1] + b) >>> 0; H[2] = (H[2] + c) >>> 0; H[3] = (H[3] + d) >>> 0;
      H[4] = (H[4] + e) >>> 0; H[5] = (H[5] + f) >>> 0; H[6] = (H[6] + g) >>> 0; H[7] = (H[7] + h) >>> 0;
    }
    const out = [];
    for (let i = 0; i < 8; i++) out.push((H[i] >>> 24) & 255, (H[i] >>> 16) & 255, (H[i] >>> 8) & 255, H[i] & 255);
    return out;
  }

  let key = utf8Bytes(keyStr);
  if (key.length > 64) key = sha256Bytes(key);
  while (key.length < 64) key.push(0);
  const ipad = [], opad = [];
  for (let i = 0; i < 64; i++) { ipad.push(key[i] ^ 0x36); opad.push(key[i] ^ 0x5c); }
  const inner = sha256Bytes(ipad.concat(utf8Bytes(msgStr)));
  const outer = sha256Bytes(opad.concat(inner));
  return outer.map(function (b) { return ('0' + b.toString(16)).slice(-2); }).join('');
}

// ── Firma el disparador de rotacion con ROTATION_ADMIN_SECRET.
const SECRET = '<<ROTATION_ADMIN_SECRET>>';

const payload = {
  triggered_by: 'n8n-cron-90d',
  dry_run: false,
  rotate_resend: true,
  push_to_vercel: true,
  redeploy: true,
  return_values: false
};

const rawBody = JSON.stringify(payload);
const ts = Math.floor(Date.now() / 1000);
const sig = hmacSha256Hex(SECRET, ts + '.' + rawBody);

return [{ json: { rawBody: rawBody, signature: 't=' + ts + ',v0=' + sig } }];

// Estado de la propagacion a Vercel.
//
// n8n tiene bloqueado el acceso a $env, por lo que NO puede guardar un
// VERCEL_TOKEN de forma segura ni hacer el PATCH. La propagacion la realiza
// el propio endpoint /api/rotate-keys cuando tiene VERCEL_TOKEN configurado.
const r = $json;
const already = r.details && r.details.vercel && r.details.vercel.updated;

const propagation = already
  ? { done: true, results: (r.details.vercel.results || []).map(function (x) { return x.key + ':' + x.action; }), reason: null }
  : { done: false, results: [], reason: 'El endpoint no propago las env vars (' +
      ((r.details && r.details.vercel && r.details.vercel.reason) || 'motivo desconocido') +
      '). Configura VERCEL_TOKEN en Vercel para que la rotacion sea 100% automatica.' };

const safe = Object.assign({}, r);
delete safe.new_values;
safe.propagation = propagation;
return [{ json: safe }];

// Construye el reporte HTML de la rotacion (sin exponer secretos)
const r = $json;
const p = r.propagation || {};
const manual = (r.manual_action_required || []).map(function (m) {
  return '<li><b>' + m.key + '</b> - ' + m.reason + '<br><span style="color:#666">' + (m.action || '') + '</span></li>';
}).join('');
const failed = (r.keys_failed || []).map(function (f) {
  return '<li><b>' + f.key + '</b>: ' + f.reason + '</li>';
}).join('');
const rotated = (r.keys_rotated || []).map(function (k) { return '<li>' + k + '</li>'; }).join('') || '<li>ninguna</li>';
const logTxt = (r.log && r.log.persisted) ? 'persistido' : ('NO persistido (' + ((r.log && r.log.reason) || 'n/a') + ')');
const STATUS_URL = 'https://victor-ia-agent.vercel.app/api/security/rotation-status';

const html =
  '<div style="font-family:system-ui,Segoe UI,Arial;max-width:640px">' +
  '<h2 style="color:#0f172a">Rotacion automatica de keys - ' + String(r.status).toUpperCase() + '</h2>' +
  '<p><b>Ejecutada:</b> ' + r.rotated_at + '<br>' +
  '<b>Proxima rotacion:</b> ' + r.next_rotation + ' (' + r.days_until_next + ' dias)<br>' +
  '<b>Duracion:</b> ' + r.duration_ms + ' ms</p>' +
  '<h3>Rotadas automaticamente</h3><ul>' + rotated + '</ul>' +
  (failed ? '<h3 style="color:#b91c1c">Fallos</h3><ul>' + failed + '</ul>' : '') +
  '<h3>Requiere accion manual</h3><ul>' + (manual || '<li>ninguna</li>') + '</ul>' +
  '<h3>Propagacion a Vercel</h3><p>' + (p.done ? 'OK: ' + (p.results || []).join(', ') : (p.reason || 'sin datos')) + '</p>' +
  '<h3>Auditoria</h3><p><a href="' + STATUS_URL + '">' + STATUS_URL + '</a></p>' +
  '<p style="color:#64748b;font-size:12px">Log en Supabase: ' + logTxt + '</p>' +
  '</div>';

return [{ json: {
  subject: '[Victor IA] Rotacion de keys ' + String(r.status).toUpperCase() + ' - proxima ' + String(r.next_rotation).slice(0, 10),
  html: html
} }];

// Reporte de FALLO CRITICO
const r = $json || {};
const err = (r.errors && r.errors[0] && r.errors[0].message) || r.error || r.reason || JSON.stringify(r).slice(0, 500);
const STATUS_URL = 'https://victor-ia-agent.vercel.app/api/security/rotation-status';

const html =
  '<div style="font-family:system-ui,Segoe UI,Arial;max-width:640px">' +
  '<h2 style="color:#b91c1c">FALLO CRITICO - Rotacion automatica de keys</h2>' +
  '<p>El workflow <b>Victor IA Agent - Auto Key Rotation (90d)</b> no pudo completar la rotacion.</p>' +
  '<p><b>Error:</b><br><code style="background:#f1f5f9;padding:8px;display:block">' + err + '</code></p>' +
  '<p><b>Accion requerida:</b> revisar el workflow en n8n y ejecutar manualmente:<br>' +
  '<code>node scripts/trigger-rotation.js</code></p>' +
  '<p>Estado actual: <a href="' + STATUS_URL + '">' + STATUS_URL + '</a></p>' +
  '</div>';

return [{ json: { subject: '[CRITICO] Fallo en rotacion automatica de keys - Victor IA Agent', html: html } }];
